np.random.seed(0); random.seed(0); gs.random.seed(0)

from geomstats.geometry.special_orthogonal import SpecialOrthogonal
from geomstats.learning.exponential_barycenter import ExponentialBarycenter
so3 = SpecialOrthogonal(n=3)
def rot(t):
    return gs.array([[np.cos(t), -np.sin(t), 0.0], [np.sin(t), np.cos(t), 0.0], [0.0, 0.0, 1.0]])
X = gs.stack([rot(0.0), rot(0.9)])
est = np.asarray(ExponentialBarycenter(so3).fit(X, weights=gs.array([2.0, 1.0])).estimate_)
result = {'angle': round(float(np.arctan2(est[1, 0], est[0, 0])), 5)}

